(* [comment removed for export] *)
Lemma rg2_X2 : forall (nolast f : bool) regs m (s pslw swpl dwpl : Z),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 112)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (if nolast then 1 else 0))) ->
  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 13 = Z_to_bv 64 swpl -> getr regs 14 = Z_to_bv 64 dwpl ->
  (nolast = false -> getr regs 26 = Z_to_bv 64 pslw /\ getr regs 30 = Z_to_bv 64 (if f then 1 else 0)) ->
  exists regs',
    msteps SEGS (mkst regs (0x7b68c : word) m rom) (mkst regs' (if nolast then (0x7bf48 : word) else (0x7b6d0 : word)) m rom)
    /\ (nolast = false -> getr regs' 7 = Z_to_bv 64 (pslw + 4) /\ getr regs' 13 = Z_to_bv 64 (4 * swpl) /\ getr regs' 14 = Z_to_bv 64 (4 * dwpl)
                          /\ getr regs' 11 = Z_to_bv 64 (if f then 1 else 0))
    /\ regs_agree (fun r => In r [7; 10; 11; 13; 14]%list) regs regs'.
